internal final class EcoResProductInformationDialog_frm_EventHandler
{
}

Method.Source:
/// <summary>
/// data source InventTable on activated event
/// </summary>
/// <param name = "sender">form data source</param>
/// <param name = "e">event args</param>
[FormDataSourceEventHandler(formDataSourceStr(EcoResProductInformationDialog, InventTable), FormDataSourceEventType::Activated),
 SuppressBPWarning('BPParameterNotUsed', 'False positive')]
public static void InventTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormRun formRun = sender.formRun();
    formRun.NDXsetMagentoOPKEnabled(formRun);
}
